SELECT r.r_reason_desc AS reason_desc, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_return_amount) AS total_return_amount, AVG(cr.cr_return_quantity) AS avg_return_qty, CASE WHEN SUM(cr.cr_net_loss) < 1000 THEN 'Low' WHEN SUM(cr.cr_net_loss) BETWEEN 1000 AND 5000 THEN 'Medium' ELSE 'High' END AS loss_category, RANK() OVER (ORDER BY SUM(cr.cr_net_loss) DESC) AS loss_rank FROM catalog_returns cr JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN household_demographics hd ON cr.cr_refunded_hdemo_sk = hd.hd_demo_sk WHERE cr.cr_returned_date_sk BETWEEN 19990101 AND 19991231 GROUP BY r.r_reason_desc
